package com.ghostlock.app.data.profile

/**
 * GLKv3 golden bytes for the shared fixture document.
 *
 * SELECTION_HEX is the NATIVE golden of the fixture that declares the queue
 * selection: make -C src glkv3-golden-hex, 3920 hex chars (was 3964 before M5,
 * -44 = the backend.<id>.steps entry the app no longer emits).
 *
 * NO_SELECTION_HEX is the APP-PATH encoding of the same document with no
 * selection declared (zero-new-bytes pin). Re-frozen in M5 from the production
 * path ProfileLayout -> NativeProfileDocument.from -> adapter -> Glkv3Encoder:
 * 3766 hex chars, was 3858 before M5 (-92 = the removed steps entry). The
 * Kotlin encoder must reproduce both byte for byte.
 */
internal object Glkv3Golden {
    const val SELECTION_HEX =
        ""

    const val NO_SELECTION_HEX =
        ""
}
